/** 한마디 입력과 패스 API를 제공합니다. */
package com.dandimate.durooduroo.memory.controller;
import com.dandimate.durooduroo.common.api.ApiResponse; import com.dandimate.durooduroo.common.exception.BusinessException; import com.dandimate.durooduroo.member.repository.MemberRepository; import com.dandimate.durooduroo.memory.domain.*; import com.dandimate.durooduroo.memory.dto.MemoryEntryRequest; import com.dandimate.durooduroo.memory.repository.MemoryEntryRepository; import com.dandimate.durooduroo.photo.repository.PhotoRepository; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/photos/{photoId}/entries") public class MemoryController{
 private final PhotoRepository photos; private final MemberRepository members; private final MemoryEntryRepository entries; private final com.dandimate.durooduroo.room.service.RoomStateService roomStates;
 public MemoryController(PhotoRepository p,MemberRepository m,MemoryEntryRepository e,com.dandimate.durooduroo.room.service.RoomStateService roomStates){photos=p;members=m;entries=e;this.roomStates=roomStates;}
 @PostMapping public ApiResponse<MemoryEntry> create(@PathVariable String photoId,@RequestHeader(required=false) String authorization,@RequestBody MemoryEntryRequest req){var photo=photos.findById(photoId).orElseThrow(()->new BusinessException("PHOTO_NOT_FOUND","사진이 없습니다."));String token=com.dandimate.durooduroo.common.auth.MemberTokenResolver.resolve(authorization,req.memberToken());var member=members.findByRoomIdAndMemberToken(photo.getRoomId(),token).orElseThrow(()->new BusinessException("MEMBER_FORBIDDEN","참여자만 작성할 수 있습니다."));boolean first=member.getId().equals(photo.getMemberId());roomStates.require(photo.getRoomId(),first?com.dandimate.durooduroo.room.domain.RoomAction.UPLOAD_OR_FIRST_ENTRY:com.dandimate.durooduroo.room.domain.RoomAction.ADDON_OR_PASS);if(entries.existsByPhotoIdAndMemberId(photoId,member.getId()))throw new BusinessException("DUPLICATE_ENTRY","이미 답변 또는 패스했습니다.");if(!req.skip()&&(req.text()==null||req.text().isBlank()))throw new BusinessException("EMPTY_CONTENT","답변 내용은 필수입니다.");var e=entries.save(MemoryEntry.create(photo.getRoomId(),photoId,member.getId(),req.skip()?null:req.text(),req.skip()?EntryStatus.SKIPPED:EntryStatus.ANSWERED));if(first&&!req.skip())roomStates.onFirstEntryConfirmed(photo.getRoomId());return ApiResponse.success(e);}
}
